// Checks the TypeScript port of html/atom against vectors generated by the real
// Go package (ts/tools/gen-atom-vectors). The Go constants, hash table and
// atomText are also parsed from table.go, so every copy in table.ts is checked.

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import * as atom from "./atom.ts";
import * as T from "./table.ts";

interface GoConstant {
  name: string;
  value: number;
  string: string;
}

interface LookupVector {
  kind: string;
  input: string;
  atom: number;
}

interface StringVector {
  input: string;
  goHex: string;
  js: string;
  valid: boolean;
}

interface Vectors {
  goVersion: string;
  hash0: number;
  maxAtomLen: number;
  tableLen: number;
  table: Record<string, number>;
  atomText: string;
  counts: Record<string, number>;
  constants: GoConstant[];
  lookup: LookupVector[];
  string: StringVector[];
}

const v: Vectors = JSON.parse(
  readFileSync(new URL("./testdata/atom_vectors.json", import.meta.url), "utf8"),
);

function bytesOf(hex: string): Uint8Array {
  return new Uint8Array(Buffer.from(hex, "hex"));
}

// The exported atom constants of table.ts: every numeric export except hash0
// and maxAtomLen.
function exportedConstants(): Map<string, number> {
  const out = new Map<string, number>();
  const ns = T as unknown as Record<string, unknown>;
  for (const key of Object.keys(ns)) {
    if (key === "hash0" || key === "maxAtomLen") continue;
    const val = ns[key];
    if (typeof val === "number") out.set(key, val);
  }
  return out;
}

test("table.ts exports exactly the Go atom constants, with the Go values", () => {
  const got = exportedConstants();
  assert.equal(got.size, v.constants.length, "number of exported atom constants");
  const ns = T as unknown as Record<string, unknown>;
  for (const c of v.constants) {
    assert.equal(ns[c.name], c.value, `constant ${c.name}`);
  }
  assert.deepEqual(
    [...got.keys()].sort(),
    v.constants.map((c) => c.name).sort(),
  );
});

test("AtomString matches Go Atom.String for every atom", () => {
  for (const c of v.constants) {
    assert.equal(atom.AtomString(c.value), c.string, `AtomString(${c.name})`);
  }
  assert.equal(v.constants.length, 368);
});

test("hash0, maxAtomLen, table and atomText match table.go", () => {
  assert.equal(T.hash0, v.hash0, "hash0");
  assert.equal(T.maxAtomLen, v.maxAtomLen, "maxAtomLen");
  assert.equal(T.table.length, v.tableLen, "table length");
  assert.equal(v.tableLen, 512);
  for (let i = 0; i < v.tableLen; i++) {
    assert.equal(T.table[i], v.table[String(i)] ?? 0, `table[${i}]`);
  }
  assert.equal(T.atomText, v.atomText, "atomText");
  assert.equal(v.atomText.length, 1834);
  assert.match(T.atomText, /^[\x00-\x7f]*$/, "atomText is ASCII");
});

test("Lookup returns the atom for each atom's own text", () => {
  const rows = v.lookup.filter((r) => r.kind === "atom");
  assert.equal(rows.length, v.constants.length);
  for (const r of rows) {
    assert.equal(atom.Lookup(bytesOf(r.input)), r.atom, `Lookup(${r.input})`);
  }
});

test("Lookup matches Go for upper-case forms of atoms", () => {
  const rows = v.lookup.filter((r) => r.kind === "upper");
  assert.equal(rows.length, v.constants.length);
  for (const r of rows) {
    assert.equal(atom.Lookup(bytesOf(r.input)), r.atom, `Lookup(upper ${r.input})`);
  }
});

test("Lookup matches Go for one-edit variants of atoms", () => {
  const rows = v.lookup.filter((r) => r.kind === "variant");
  assert.ok(rows.length >= 1000, `variant vectors: ${rows.length}`);
  for (const r of rows) {
    assert.equal(atom.Lookup(bytesOf(r.input)), r.atom, `Lookup(variant ${r.input})`);
  }
});

test("Lookup matches Go for other byte strings", () => {
  const rows = v.lookup.filter((r) => r.kind === "other");
  assert.ok(rows.length >= 2000, `other vectors: ${rows.length}`);
  for (const r of rows) {
    assert.equal(atom.Lookup(bytesOf(r.input)), r.atom, `Lookup(other ${r.input})`);
  }
});

test("String matches Go string(bytes) for every sampled input", () => {
  assert.ok(v.string.length >= 2000, `String vectors: ${v.string.length}`);
  for (const r of v.string) {
    const got = atom.String(bytesOf(r.input));
    assert.equal(got, r.js, `String(${r.input})`);
    if (r.valid) {
      // Valid UTF-8: the JavaScript string re-encodes to the exact Go bytes.
      assert.equal(Buffer.from(got, "utf8").toString("hex"), r.goHex, `bytes of String(${r.input})`);
    }
  }
});

test("vector counts are as generated", () => {
  assert.equal(v.counts["atom"], 368);
  assert.equal(v.counts["upper"], 368);
  assert.ok((v.counts["other"] ?? 0) >= 2000, "at least 2000 other byte strings");
  assert.equal(v.lookup.length, Object.values(v.counts).reduce((a, b) => a + b, 0));
});

test("hand-written spot checks", () => {
  assert.equal(atom.Lookup(new Uint8Array(Buffer.from("div"))), T.Div);
  assert.equal(atom.AtomString(T.Div), "div");
  assert.equal(atom.AtomString(T.AnnotationXml), "annotation-xml");
  assert.equal(atom.Lookup(new Uint8Array(0)), 0);
  assert.equal(atom.Lookup(new Uint8Array(Buffer.from("DIV"))), 0);
  assert.equal(atom.Lookup(new Uint8Array(Buffer.from("onsecuritypolicyviolation"))), T.Onsecuritypolicyviolation);
  assert.equal(atom.Lookup(new Uint8Array(Buffer.from("onsecuritypolicyviolationx"))), 0);
  assert.equal(atom.String(new Uint8Array(Buffer.from("span"))), "span");
  assert.equal(atom.String(new Uint8Array(Buffer.from("custom-tag"))), "custom-tag");
  assert.equal(atom.String(new Uint8Array([0x61, 0xff, 0x62])), "a�b");
  assert.equal(atom.AtomString(0), "");
});
